    pub const BASE_LISTENER_VTABLE: u32 = 0x00E3_2828;
    pub const LISTENER_VTABLE_LEN: usize = 4;
    /// Its third table at `+0x48` (the destructor).
    pub const BASE_THIRD_VTABLE: u32 = 0x00E3_2838;
    /// Offsets of the three tables in an object.
    pub const OBJECT_LISTENER: u32 = 0x3C;
    pub const OBJECT_THIRD: u32 = 0x48;
    /// GUID of an object.
    pub const OBJECT_GUID: u32 = 0x20;
    /// Flags of the listener of an object, bit 0 — switched on.
    pub const LISTENER_FLAGS: u32 = 4;

    /// `void Name(Variable*, u32 hash)`, cdecl: the variable of a message.
    pub const MESSAGE_VARIABLE: u32 = 0x0040_8260;
    /// `void Release(Variable*)`, cdecl.
    pub const MESSAGE_RELEASE: u32 = 0x0040_8310;
    /// `void Subscribe(Listener*, Variable*, u16 priority)`, cdecl.
