/// Who patches a place.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Owner {
    /// `doctor_live.asi`.
    Live,
    /// `doctor_render.asi`.
    Render,
    /// `doctor_crash.asi`.
    Crash,
    /// `doctor_platform.asi`.
    Platform,
}

impl Owner {
    pub fn name(self) -> &'static str {
        match self {
            Self::Live => "doctor_live",
            Self::Render => "doctor_render",
            Self::Crash => "doctor_crash",
            Self::Platform => "doctor_platform",
        }
    }
}

/// One place of the game a module of the toolkit writes to.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Claim {
    pub owner: Owner,
    pub address: u32,
    pub len: u32,
    /// A pointer in the data of the game, not code.
    pub data: bool,
}

const fn code(owner: Owner, address: u32, len: u32) -> Claim {
    Claim {
        owner,
        address,
        len,
        data: false,
    }
}

const fn data(owner: Owner, address: u32) -> Claim {
    Claim {
        owner,
        address,
        len: 4,
        data: true,
    }
}

