/// Whether `[a, a + a_len)` and `[b, b + b_len)` share a byte.
pub const fn overlap(a: u32, a_len: u32, b: u32, b_len: u32) -> bool {
    (a as u64) < b as u64 + b_len as u64 && (b as u64) < a as u64 + a_len as u64
}

/// The claim of the toolkit's modules a place `[address, address + len)`
/// touches.
pub fn claimed(address: u32, len: u32) -> Option<&'static Claim> {
    CLAIMS
        .iter()
        .find(|c| overlap(address, len, c.address, c.len))
}

/// The place of any module's edition check that `[address, address + len)`
/// touches: a patch there would make that module refuse to work.
pub fn checked(address: u32, len: u32) -> Option<(Owner, &'static Check)> {
    let tables: [(Owner, &'static [Check]); 4] = [
        (Owner::Live, crate::edition::CHECKS),
        (Owner::Render, crate::render::CHECKS),
        (Owner::Crash, crate::crash::CHECKS),
        (Owner::Platform, CHECKS),
    ];
    for (owner, table) in tables {
        for c in table {
            if overlap(address, len, c.address, c.bytes.len() as u32) {
                return Some((owner, c));
            }
        }
    }
    None
}

/// Why a native mod cannot have a hook at a place.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum HookRefusal {
    /// Outside the code of the game.
    NotCode,
    /// A module of the toolkit patches it.
    Claimed(Owner),
    /// A module of the toolkit checks its bytes and would refuse to work.
    Checked(Owner, u32),
}

impl std::fmt::Display for HookRefusal {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::NotCode => write!(f, "the place is not in the code of the game"),
            Self::Claimed(o) => write!(f, "{} patches this place", o.name()),
            Self::Checked(o, at) => {
                write!(f, "{} checks the bytes at {at:#010x}", o.name())
            }
        }
    }
}

/// Whether a native mod may patch `[address, address + len)`: inside the
/// code of the game and clear of every claim and every check of the
/// toolkit's modules. Places other mods took are the platform's to check
/// (it keeps them while the game runs).
pub fn mod_hook_allowed(address: u32, len: u32) -> Result<(), HookRefusal> {
    let end = address as u64 + len as u64;
    if len == 0 || address < crate::addr::TEXT_START || end > crate::addr::TEXT_END as u64 {
        return Err(HookRefusal::NotCode);
    }
    if let Some(c) = claimed(address, len) {
        return Err(HookRefusal::Claimed(c.owner));
    }
    if let Some((owner, c)) = checked(address, len) {
        return Err(HookRefusal::Checked(owner, c.address));
    }
    Ok(())
}

/// Checks the build for the module: the header of PC 1.0.789.0 and
/// [`CHECKS`].
pub fn check(read: &mut dyn FnMut(u32, &mut [u8]) -> bool) -> Result<(), crate::edition::Mismatch> {
    crate::edition::check_with(read, CHECKS)
}

/// [`check`] on the bytes of an executable file.
pub fn check_file(data: &[u8]) -> Result<(), crate::edition::Mismatch> {
    crate::edition::check_file_with(data, CHECKS)
}

