#[cfg(test)]
mod tests {
    use super::*;

    fn checks_of(owner: Owner) -> &'static [Check] {
        match owner {
            Owner::Live => crate::edition::CHECKS,
            Owner::Render => crate::render::CHECKS,
            Owner::Crash => crate::crash::CHECKS,
            Owner::Platform => CHECKS,
        }
    }

    #[test]
    fn no_two_modules_patch_the_same_place() {
        for (i, a) in CLAIMS.iter().enumerate() {
            for b in &CLAIMS[i + 1..] {
                assert!(
                    !overlap(a.address, a.len, b.address, b.len),
                    "{} at {:#010x} and {} at {:#010x} overlap",
                    a.owner.name(),
                    a.address,
                    b.owner.name(),
                    b.address
                );
            }
        }
    }

    #[test]
    fn no_module_checks_what_another_one_patches() {
        for claim in CLAIMS {
            for owner in [Owner::Live, Owner::Render, Owner::Crash, Owner::Platform] {
                if owner == claim.owner {
                    continue;
                }
                for c in checks_of(owner) {
                    assert!(
                        !overlap(claim.address, claim.len, c.address, c.bytes.len() as u32),
                        "{} patches {:#010x}, {} checks {:#010x} ({})",
                        claim.owner.name(),
                        claim.address,
                        owner.name(),
                        c.address,
                        c.what
                    );
                }
            }
        }
    }

    #[test]
    fn a_patched_instruction_is_checked_by_its_module() {
        for claim in CLAIMS.iter().filter(|c| !c.data) {
            let covered = checks_of(claim.owner).iter().any(|c| {
                c.address <= claim.address
                    && claim.address + claim.len <= c.address + c.bytes.len() as u32
            });
            assert!(
                covered,
                "{} patches {:#010x} without checking its bytes",
                claim.owner.name(),
                claim.address
            );
        }
    }

    #[test]
    fn the_claims_list_the_patches_of_the_modules() {
        let of = |owner| -> Vec<(u32, u32)> {
            CLAIMS
                .iter()
                .filter(|c| c.owner == owner)
                .map(|c| (c.address, c.len))
                .collect()
        };
        assert_eq!(of(Owner::Render), crate::render::PATCHES);
        assert_eq!(of(Owner::Platform), PATCHES);
        assert_eq!(
            of(Owner::Crash),
            [(crate::crash::BUS_HOOK, 6), (crate::crash::LUA_THROW, 5)]
        );
    }

    #[test]
    fn a_mod_hook_is_refused_where_the_toolkit_lives() {
        // The entry of the bus: doctor_live jumps from it.
        assert_eq!(
            mod_hook_allowed(crate::addr::MESSAGE_SEND, 5),
            Err(HookRefusal::Claimed(Owner::Live))
        );
        // One byte into the crash module's instruction.
        assert_eq!(
            mod_hook_allowed(crate::crash::BUS_HOOK + 5, 5),
            Err(HookRefusal::Claimed(Owner::Crash))
        );
        // Bytes the live module only checks.
        assert_eq!(
            mod_hook_allowed(0x0046_C523, 6),
            Err(HookRefusal::Checked(Owner::Live, 0x0046_C523))
        );
        // The data of the game and addresses outside it.
        assert_eq!(mod_hook_allowed(0x0122_3410, 4), Err(HookRefusal::NotCode));
        assert_eq!(mod_hook_allowed(0x0040_2000, 0), Err(HookRefusal::NotCode));
        assert_eq!(mod_hook_allowed(0xFFFF_FFFE, 8), Err(HookRefusal::NotCode));
        // A function nobody of the toolkit touches (`TriggerAuto`'s handler).
        assert_eq!(mod_hook_allowed(0x0047_7EF0, 6), Ok(()));
    }

    #[test]
    fn the_filter_hook_is_whole_instructions() {
        let c = CHECKS
            .iter()
            .find(|c| c.address == addr::FILTER_HOOK)
            .unwrap();
        // xor al, al; test esi, esi; je rel32 (to FILTER_MISS).
        assert_eq!(c.bytes.len() as u32, addr::FILTER_HOOK_LEN);
        assert_eq!(c.bytes[..6], [0x32, 0xC0, 0x85, 0xF6, 0x0F, 0x84]);
        let rel = i32::from_le_bytes([c.bytes[6], c.bytes[7], c.bytes[8], c.bytes[9]]);
        assert_eq!(
            (addr::FILTER_RESUME as i64 + rel as i64) as u32,
            addr::FILTER_MISS
        );
        assert_eq!(
            addr::FILTER_HOOK + addr::FILTER_HOOK_LEN,
            addr::FILTER_RESUME
        );
    }

    #[test]
    fn the_hooked_calls_call_what_the_module_expects() {
        for (site, callee) in [
            (addr::START_CALL, addr::START_CALLEE),
            (addr::LUA_MANAGER_CALL, addr::LUA_MANAGER_CTOR),
            (addr::TICK_CALL, addr::TICK_CALLEE),
            (addr::XINPUT_CALL, addr::XINPUT_GET_STATE),
        ] {
            let c = CHECKS
                .iter()
                .find(|c| c.address <= site && site + 5 <= c.address + c.bytes.len() as u32)
                .unwrap();
            let b = &c.bytes[(site - c.address) as usize..];
            assert_eq!(b[0], 0xE8);
            let rel = i32::from_le_bytes([b[1], b[2], b[3], b[4]]);
            assert_eq!((site as i64 + 5 + rel as i64) as u32, callee);
        }
    }

    #[test]
    fn the_method_tables_of_base_are_what_the_module_copies() {
        let words = |address: u32| -> Vec<u32> {
            let c = CHECKS.iter().find(|c| c.address == address).unwrap();
            c.bytes
                .chunks(4)
                .map(|w| u32::from_le_bytes([w[0], w[1], w[2], w[3]]))
                .collect()
        };
        let object = words(addr::BASE_VTABLE);
        assert_eq!(object.len(), addr::BASE_VTABLE_LEN);
        assert_eq!(object[0], addr::BASE_DTOR);
        let listener = words(addr::BASE_LISTENER_VTABLE);
        assert_eq!(listener.len(), addr::LISTENER_VTABLE_LEN);
        // The listener table ends where the third one starts.
        assert_eq!(
            addr::BASE_LISTENER_VTABLE + 4 * addr::LISTENER_VTABLE_LEN as u32,
            addr::BASE_THIRD_VTABLE
        );
    }

    /// Another build (here: memory that is not an executable at all, and
    /// the right header with other code) is refused before anything is
    /// installed.
    #[test]
    fn the_platform_refuses_another_build() {
        use crate::edition::Mismatch;
        assert!(matches!(
            check(&mut |_, buf| {
                buf.fill(0);
                true
            }),
            Err(Mismatch::Header(_))
        ));
        let Some(dir) = std::env::var_os("EARS_GF2_DIR") else {
            return;
        };
        let Ok(mut data) = std::fs::read(std::path::Path::new(&dir).join("godfather2.exe")) else {
            return;
        };
        // One byte of the class registration differs.
        let at = (addr::CLASS_REGISTER - crate::edition::IMAGE_BASE) as usize;
        data[at] ^= 0xFF;
        assert_eq!(
            check_file(&data),
            Err(Mismatch::Bytes {
                address: addr::CLASS_REGISTER,
                what: CHECKS[0].what
            })
        );
    }

    /// The table against the real executable (needs the game).
    #[test]
    fn platform_checks_match_the_game() {
        let Some(dir) = std::env::var_os("EARS_GF2_DIR") else {
            return;
        };
        let Ok(data) = std::fs::read(std::path::Path::new(&dir).join("godfather2.exe")) else {
            return;
        };
        assert_eq!(check_file(&data), Ok(()));
    }
}
